// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Wide admissible domain: nonzero deposit >= nonzero collect, and deposit >= MinSum.
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, depositAmount);

        address actor = address(0xA11CE);
        uint256 minSum = depositAmount; // ensures balances[actor] >= MinSum after deposit

        // Required setup: deploy LogFile and wire it before Initialized() is called.
        C_LogFile log = new C_LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(minSum);
        c.Initialized();

        // Give the actor enough ether and deposit through the public payable entry.
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Reference must let the actor collect; mutant fails the guard on address(0)'s balance.
        vm.prank(actor);
        bool ok = true;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = c.balances(actor);

        // Universal rule: when the caller has enough balance and enough balance to cover _am,
        // Collect must succeed and the caller's balance must decrease by exactly _am.
        assertTrue(ok && balanceAfter == depositAmount - collectAmount);
    }
}

contract C_LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
